head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00051";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.returnKey, formKey, keyValue, returnKey

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00051.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_75_onclick
 * @description 「창닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_75_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00051.img_75_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {*} mktpartcNo mktpartcNo
 * @param {String} mktpartcKorNm mktpartcKorNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (mktpartcNo, mktpartcKorNm) {
    let str = "";
    str += "mktpartcNo : " + mktpartcNo + "\n";
    str += "mktpartcKorNm : " + mktpartcKorNm + "\n";
    const returnKey = (String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))));
    try {
        const code = (mktpartcNo == null || mktpartcNo === "") ? "-" : mktpartcNo;
        const name = (mktpartcKorNm == null || mktpartcKorNm === "") ? "-" : mktpartcKorNm;
        const obj = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).Potential).Provider;
        const frameId = obj.ActiveFrame.FrameID;
        const frame = obj.Provider(frameId).ActiveFrame;
        frame.fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name);
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00051' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
